def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]

    # Count opponent's defections and consecutive tail behavior
    opp_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    opp_coop = n - opp_def
    rate = opp_def / n

    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    tail_cc = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and opp[i] == 'C':
            tail_cc += 1
        else:
            break

    remaining = 100 - n

    # Very reliable cooperator: keep cooperating, but exploit only at the very end.
    if opp_def <= 1:
        if remaining <= 1:
            return 'D'
        return 'C'

    # Persistent defector: don't keep feeding them, but probe rarely to re-open.
    if rate > 0.8:
        if n % 20 == 0:
            return 'C'
        return 'D'

    # Opponent just defected: retaliate, but forgive isolated defections after cooperation.
    if last_opp == 'D':
        if tail_def >= 3:
            return 'D'
        # If the defection looks like noise after a long CC run and lots of match left, forgive.
        if tail_cc >= 6 and remaining > 20 and rng.random() < 0.5:
            return 'C'
        if rate > 0.35:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if rate > 0.5:
        # Untrustworthy: mostly punish/exploit rather than reward.
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    if rate > 0.25:
        # Moderately defective: cooperate mostly, punish occasional opportunistic play.
        if tail_cc >= 3 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Opponent mostly cooperates. Rare probe to test for exploitability.
    if tail_cc >= 4 and n >= 6 and rng.random() < 0.06:
        return 'D'

    # Endgame: against a cooperative opponent, defect in final rounds.
    if remaining <= 2:
        if rng.random() < 0.7:
            return 'D'
    if remaining <= 4 and rng.random() < 0.25:
        return 'D'

    return 'C'
